function main() {
function sum(integer first, integer ...rest) {
  let integer total = first;
  for (let v in rest) {
    total = total + v;
  }
  return total;
}
print(sum(1, 2, 3));
}

function main() {
function fact(integer n) {
  if (n <= 1) {
    return 1;
  }
  return n * fact(n - 1);
}
print(fact(5));
}

