  }
  public integer sum() {
    return this.x + this.y;
  }
}
function main() {
  let Point p = new Point(2, 3);
  print(p.sum());
}

class Parent {
  private string name;
  public Parent(string name) {
    this.name = name;
  }
  public string getName() {
    return this.name;
  }
}
class Child extends Parent {
  public Child(string name) {
    super(name);
  }
  public string describe() {
    return "child " + this.getName();
  }
}
function main() {
  print(new Child("ada").describe());
}

