print(o.name);
print(o.age);
}

function main() {
function describe(object value) {
  return match value {
    null => "empty",
    [first, second, ...remaining] if first == 1 =>
      "array " + second + " tail " + remaining.length,
    {name: person, active: true} => "person " + person,
    _ => "other"
  };
}
print(describe(null));
print(describe([1, 2, 3, 4]));
print(describe({name: "Ada", active: true}));
}

