import System.utils.Collections.HashMap;
function main() {
  let HashMap m = new HashMap();
  m.set("a", 1);
  m.set("b", 2);
  print(m.get("a"));
  print(m.has("b"));
  print(m.has("z"));
  print(m.size());
  print(m.get("z"));
  print(m.getOrDefault("zz", -1));
  m.remove("a");
  print(m.size());
  m.clear();
  print(m.isEmpty());
  print(m.keys());
  print(m.values());
  print(m.entries());
}

