import System.utils.Collections.Trie;
function main() {
  let t = new Trie();
  t.insert("car");
  t.insert("card");
  print(t.search("car"));
  print(t.search("cab"));
  print(t.startsWith("ca"));
  print(t.size());
  print(t.getAllWords());
  print(t.getWordsWithPrefix("car"));
  print(t.remove("car"));
  print(t.search("car"));
}

import System.concurrent.Thread
integer function add(integer left, integer right) {
  return left + right;
}
integer function getAnswer() {
  return 42;
}
function main() {
  let ThreadHandle worker = Thread.start(add, [20, 22]);
  print(worker.join());
  print(worker.isAlive());
  let ThreadHandle solo = Thread.start(getAnswer);
  print(solo.join());
}

import System.concurrent.Thread
function bail() {
  System.process.exit(7);
}
function main() {
  let ThreadHandle worker = Thread.start(bail);
  worker.join();
  print("unreachable");
}

