function main() {
  let integer a = 1;
  let integer b = 2;
  let integer c = 3;
  let integer d = 4;
  let integer e = 5;
  let integer f = 6;
  switch (a) {
    case 1: {
      switch (b) {
        case 2: {
          switch (c) {
            case 3: {
              switch (d) {
                case 4: {
                  switch (e) {
                    case 5: {
                      switch (f) {
                        case 6: { print("deep6"); }
                        default: { print("f-other"); }
                      }
                    }
                    default: { print("e-other"); }
                  }
                }
                default: { print("d-other"); }
              }
            }
            default: { print("c-other"); }
          }
        }
        default: { print("b-other"); }
      }
    }
    default: { print("a-other"); }
  }
  print("end");
}

function main() {
  let string channel = "web";
  let integer tier = 2;
  let integer attempt = 1;
  let string receipt = "";
  for (let i = 0; i < 2; i = i + 1) {
    switch (channel) {
      case "web": {
        print("channel web");
        switch (tier) {
          case 1: {
            print("tier basic");
          }
          case 2: {
            print("tier pro");
            switch (attempt) {
              case 0: {
                print("attempt zero");
              }
              case 1: {
                print("attempt one");
                switch (i) {
                  case 0: {
                    receipt = "first";
                  }
                  default: {
                    receipt = "again";
                  }
                }
                print(receipt);
              }
              default: {
                print("attempt other");
              }
            }
          }
          default: {
            print("tier other");
          }
        }
        break;
      }
      default: {
        print("channel other");
      }
    }
  }
  print(receipt);
}

