}

function main() {
  let integer hits = 0;
  let integer kind = 2;
  switch (kind) {
    case 1: { print("one"); }
    case 2: {
      for (let i = 0; i < 3; i = i + 1) {
        switch (i) {
          case 0: { hits = hits + 10; }
          case 1: { hits = hits + 1; }
          default: { hits = hits + 100; }
        }
      }
      print(hits);
    }
    default: { print("other"); }
  }
  print("done");
}

