interface Gateway {
  integer process(integer amount);
  string name();
}
class StripeGateway implements Gateway {
  public integer process(integer amount) { return amount + 10; }
  public string name() { return "stripe"; }
}
abstract class AbstractPayment {
  protected Gateway gateway;
  public AbstractPayment(Gateway gateway) { this.gateway = gateway; }
  public abstract integer makePayment(integer amount);
  public integer configurePaymentGateway() {
    return this.gateway.name().length;
  }
}
class CardPayment extends AbstractPayment {
  public CardPayment(Gateway gateway) { super(gateway); }
  public integer makePayment(integer amount) {
    return this.gateway.process(amount);
  }
}
function main() {
  let Gateway g = new StripeGateway();
  let payments = [new CardPayment(g)];
  for (let payment of payments) {
    print(payment.makePayment(5));
    print(payment.configurePaymentGateway());
  }
}

class Base {
  integer size;
  public Base(integer size) { this.size = size; }
  public virtual integer fee() { return this.size; }
}
class Child extends Base {
  integer bonus;
  public Child(integer size, integer bonus) {
    super(size);
    this.bonus = bonus;
  }
  public override integer fee() {
    return super.fee() + this.bonus;
  }
}
function main() {
  let Child c = new Child(10, 5);
  print(c.fee());
}

class Shape { public virtual integer area() { return 0; } }
class Square extends Shape {
  integer side;
  public Square(integer side) { this.side = side; }
  public override integer area() { return this.side * this.side; }
}
class Rect extends Shape {
  integer w;
  integer h;
  public Rect(integer w, integer h) { this.w = w; this.h = h; }
  public override integer area() { return this.w * this.h; }
}
function main() {
  let shapes = [new Square(3), new Rect(2, 5)];
  let integer total = 0;
  for (let s of shapes) {
    total = total + s.area();
  }
  print(total);
}

class Base {
  static integer processed = 0;
}
class Child extends Base {
  public integer work() {
    Child.processed = Child.processed + 1;
    return Child.processed;
  }
}
function main() {
  let Child c = new Child();
  c.work();
  c.work();
  print(Base.processed);
}
